struct TrieNode {
    std::unordered_map<int, TrieNode*> children;
};

class Solution {
public:
    int countDistinct(std::vector<int>& nums, int k, int p) {
        TrieNode* root = new TrieNode();
        int count = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            TrieNode* curr = root;
            int div = 0;
            for (int j = i; j < n; ++j) {
                if (nums[j] % p == 0) ++div;
                if (div > k) break;
                if (!curr->children.count(nums[j])) {
                    curr->children[nums[j]] = new TrieNode();
                    ++count;
                }
                curr = curr->children[nums[j]];
            }
        }
        return count;
    }
};

class Solution {
    static class Node {
        java.util.Map<Integer, Node> children = new java.util.HashMap<>();
    }

    public int countDistinct(int[] nums, int k, int p) {
        Node root = new Node();
        int count = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            Node curr = root;
            int div = 0;
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) div++;
                if (div > k) break;
                if (!curr.children.containsKey(nums[j])) {
                    curr.children.put(nums[j], new Node());
                    count++;
                }
                curr = curr.children.get(nums[j]);
            }
        }
        return count;
    }
}

